import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const host=$('#world'), isTouch=('ontouchstart'in window)||navigator.maxTouchPoints>0;
if(isTouch)document.body.classList.add('mobile-layout');
$('#touch-controls').style.display=isTouch?'block':'none';
$('#hint').textContent=isTouch?'DRAG TO AIM · LEFT STICK MOVE · FIRE BUTTON SHOOTS':'WASD MOVE · MOUSE AIM · CLICK FIRE · SPACE JUMP · R RELOAD';
$('#controls-copy').innerHTML=isTouch?'Left stick to move · Drag screen to aim<br>Tap FIRE to shoot · Use icons to switch weapons':'WASD to move · Mouse to aim & fire<br>1–4 change weapon · Space to jump · R reload';
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9bdcf0);scene.fog=new THREE.Fog(0x9bdcf0,54,150);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.1,220);camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xe4faff,0x53785d,2.1));const sun=new THREE.DirectionalLight(0xfff0d0,3.2);sun.position.set(-24,40,18);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={grass:mat(0x74c86d),grass2:mat(0x58af71),road:mat(0x586c79),roadline:mat(0xe4e2ca),sand:mat(0xe6c47b),wood:mat(0xb87548),wallA:mat(0xffd5a1),wallB:mat(0xa6e3ec),wallC:mat(0xf4a4b7),roof:mat(0x825c93),roof2:mat(0x398aa6),leaf:mat(0x299e76),leaf2:mat(0x55c579),trunk:mat(0x795037),rock:mat(0x839397),white:mat(0xeaf4ed),dark:mat(0x233349),gold:mat(0xffcd65,.42,.18),neon:mat(0x46edff,.25,.3)};
function box(parent,x,y,z,w,h,d,material,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=8){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
const ground=new THREE.Mesh(new THREE.CircleGeometry(80,64),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
// Floating island edge and shoreline
const island=new THREE.Mesh(new THREE.CylinderGeometry(56,42,7,48,1),mat(0x5b8d78));island.position.y=-3.9;island.receiveShadow=true;island.castShadow=true;scene.add(island);
const beach=new THREE.Mesh(new THREE.RingGeometry(40,45,64),mats.sand);beach.rotation.x=-Math.PI/2;beach.position.y=-.04;scene.add(beach);
// Roads, plaza, and arena markings
box(scene,0,.005,0,9,.025,78,mats.road,false);box(scene,0,.018,0,.13,.025,77,mats.roadline,false);
box(scene,0,.006,0,75,.025,8,mats.road,false);box(scene,0,.02,0,75,.025,.13,mats.roadline,false);
const plaza=new THREE.Mesh(new THREE.CircleGeometry(8,40),mat(0xd5c98d));plaza.rotation.x=-Math.PI/2;plaza.position.y=.025;scene.add(plaza);
const hub=new THREE.Mesh(new THREE.CylinderGeometry(3.2,3.2,.3,8),mat(0x45698a));hub.position.set(0,.18,0);hub.castShadow=true;scene.add(hub);const hubGlow=new THREE.Mesh(new THREE.TorusGeometry(2.5,.1,8,32),mats.neon);hubGlow.rotation.x=Math.PI/2;hubGlow.position.y=.38;scene.add(hubGlow);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const o=box(scene,Math.sin(a)*3.1,.4,Math.cos(a)*3.1,.45,.45,.45,mats.gold);o.rotation.y=a}
// Simple island houses with bright trims, roofs, windows and doors
function house(x,z,color,roofColor,rot=0,scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;g.scale.setScalar(scale);scene.add(g);const wall=mat(color),roofmat=mat(roofColor);box(g,0,1.2,0,5,2.4,4,wall);const roof=new THREE.Mesh(new THREE.ConeGeometry(3.8,1.8,4),roofmat);roof.position.y=3.25;roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);box(g,-1.15,1.35,2.04,.82,.8,.08,mat(0x77cced,.35));box(g,1.15,1.35,2.04,.82,.8,.08,mat(0x77cced,.35));box(g,0,.85,2.06,.72,1.5,.12,mats.wood);box(g,0,.3,2.15,.1,.1,.12,mats.gold);box(g,0,2.15,2.09,4.7,.1,.12,mats.white);return g}
house(-16,-15,0xffd2a0,0x845d91,.15,1.08);house(17,-18,0x9ce1e8,0x347e9a,-.25,1.05);house(-20,17,0xf5a7b5,0xa0546e,-.32,1);house(20,18,0xf7d386,0x4c8790,.35,1.06);house(-34,-1,0x9edbce,0x7b638e,.8,.86);house(34,2,0xffc7a2,0x397d91,-.8,.85);
// Shelter props / crates / ramps
function crate(x,z,size=1){const c=box(scene,x,size*.5,z,size,size,size,mats.wood);box(scene,x,size*.5,z+size*.505,size*.72,size*.78,.035,mats.gold,false);return c}
for(const p of [[-8,-20],[10,-10],[-24,7],[24,-8],[-12,23],[9,24],[31,12],[-31,-14]])crate(p[0],p[1],1.2);
for(const [x,z,r] of [[-9,11,.9],[11,12,.8],[-28,-9,1.2],[27,25,1],[-29,24,1.3],[30,-24,.8]]){const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(r,0),mats.rock);rock.position.set(x,r*.55,z);rock.scale.y=.7;rock.castShadow=true;rock.receiveShadow=true;scene.add(rock)}
// Low-poly trees around the battle lanes
for(let i=0;i<48;i++){const a=i*2.399,rad=24+(i%7)*2.1,x=Math.cos(a)*rad,z=Math.sin(a)*rad;if(Math.abs(x)<6||Math.abs(z)<6)continue;const h=2.2+(i%4)*.35;cylinder(scene,x,h/2,z,.24,.38,h,mats.trunk,7);const crown=new THREE.Mesh(new THREE.ConeGeometry(1.35+(i%3)*.2,2.8+(i%4)*.2,7),i%3?mats.leaf:mats.leaf2);crown.position.set(x,h+1,z);crown.castShadow=true;crown.receiveShadow=true;scene.add(crown);const cap=new THREE.Mesh(new THREE.SphereGeometry(.72,7,5),mats.leaf2);cap.position.set(x,h+1.25,z);cap.castShadow=true;scene.add(cap)}
// Colorful sky puffs and faraway floating rock silhouettes
for(let i=0;i<12;i++){const x=-60+i*11,z=-75-(i%3)*8;const cloud=new THREE.Group();cloud.position.set(x,20+(i%4)*2,z);scene.add(cloud);for(let j=0;j<4;j++){const puff=new THREE.Mesh(new THREE.SphereGeometry(3+(j%2),10,8),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.45}));puff.position.set(j*3-4,j%2,0);cloud.add(puff)}}
// Neon loot crates are visual landmarks
for(const [x,z,c] of [[-7,6,0xff6ba5],[8,-7,0x68e8ff],[-18,4,0xffdd70],[18,8,0x8c7cff]]){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,.65,0,1.4,1.2,1.4,mat(0x263e59));const glow=box(g,0,.8,.72,1,.48,.08,mat(c,.2,.3));glow.material.emissive=new THREE.Color(c);glow.material.emissiveIntensity=.65}
// Scene variables and weapon definitions
const weapons=[
 {name:'ENERGY RIFLE',sub:'PULSE · SEMI AUTO',mag:24,reserve:120,damage:34,rate:.24,reload:1.35,spread:.009,kind:'pulse',speed:52},
 {name:'VOLT PISTOLS',sub:'DUAL · RAPID FIRE',mag:32,reserve:160,damage:17,rate:.115,reload:1.15,spread:.025,kind:'dual',speed:48},
 {name:'AK-47',sub:'ASSAULT · AUTO',mag:30,reserve:150,damage:22,rate:.105,reload:1.45,spread:.018,kind:'ak',speed:58},
 {name:'ROCKET LAUNCHER',sub:'BLAST · AREA DAMAGE',mag:4,reserve:16,damage:95,rate:.72,reload:1.8,spread:0,kind:'rocket',speed:28}
];
weapons.forEach(w=>{w.ammo=w.mag;w.reloading=0});let selected=0,player={x:0,y:1.7,z:30,yaw:0,pitch:0,health:100,shield:50,speed:9,vy:0,grounded:true},playing=false,ended=false,kills=0,timeLeft=120,lastShot=0,damageFlash=0;
const bots=[],enemyShots=[],projectiles=[],effects=[];const raycaster=new THREE.Raycaster();raycaster.far=90;const tmpV=new THREE.Vector3();
const botColors=[0xf05e79,0xffa44e,0x9a71f5,0xe852b6,0x39bba9,0xed704a,0x678cf5,0xe5bd47];
function makeBot(i){const g=new THREE.Group();const c=mat(botColors[i%botColors.length]);const accent=mat(0x26384c);const glowing=mat(0xff6c82,.3,.1);glowing.emissive=new THREE.Color(0x551529);const torso=box(g,0,1.24,0,.8,.9,.42,c);torso.userData.botId=i;const head=new THREE.Mesh(new THREE.SphereGeometry(.29,10,8),mat(0xffd2ad));head.position.y=1.97;head.castShadow=true;head.userData.botId=i;g.add(head);box(g,0,1.63,.24,.52,.11,.08,glowing);const pack=box(g,0,1.25,-.28,.56,.58,.2,accent);const arm1=box(g,-.53,1.34,.04,.22,.68,.24,c);arm1.rotation.z=-.18;const arm2=box(g,.53,1.34,.04,.22,.68,.24,c);arm2.rotation.z=.18;const leg1=box(g,-.23,.48,0,.28,.8,.34,accent);const leg2=box(g,.23,.48,0,.28,.8,.34,accent);cylinder(g,.25,1.4,.28,.09,.09,.8,mats.dark,8).rotation.x=Math.PI/2;g.position.set(Math.cos(i*6.28/8)*25,0,Math.sin(i*6.28/8)*25);g.userData={id:i,hp:100,alive:true,fire:1+i*.36,phase:i*2};g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.userData.botId=i}});scene.add(g);bots.push(g)}
for(let i=0;i<8;i++)makeBot(i);
const playerGroup=new THREE.Group();scene.add(playerGroup); // carries purely cosmetic muzzle flash
const muzzle=new THREE.PointLight(0x50eaff,0,5);playerGroup.add(muzzle);

// Player avatar and held weapon: readable in third-person, with responsive camera follow
const avatar=new THREE.Group();scene.add(avatar);const avatarMat=mat(0x38b8cf),avatarDark=mat(0x1d3d5b),skin=mat(0xf0c6a1);box(avatar,0,1.22,0,.78,.9,.42,avatarMat);const avatarHead=new THREE.Mesh(new THREE.SphereGeometry(.29,10,8),skin);avatarHead.position.y=1.96;avatar.add(avatarHead);box(avatar,-.23,.48,0,.28,.8,.34,avatarDark);box(avatar,.23,.48,0,.28,.8,.34,avatarDark);box(avatar,0,1.64,.24,.53,.12,.08,mats.neon);const playerGun=new THREE.Group();avatar.add(playerGun);box(playerGun,.38,1.4,.48,.18,.18,.66,mats.dark);box(playerGun,.38,1.4,.83,.11,.11,.3,mats.gold);
const cameraOffset=new THREE.Vector3(0,4.2,9);let cameraTarget=new THREE.Vector3(),cameraPos=new THREE.Vector3();
function setWeapon(i){selected=(i+weapons.length)%weapons.length;$$('.weapon-btn').forEach(b=>b.classList.toggle('active',Number(b.dataset.weapon)===selected));const w=weapons[selected];$('#weapon-name').textContent=w.name;$('#weapon-sub').textContent=w.sub;$('#ammo').textContent=w.ammo;$('#reserve').textContent='/ '+w.reserve}
$$('.weapon-btn').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();setWeapon(+b.dataset.weapon)}));
function showNotice(text){const n=$('#notice');n.textContent=text;n.classList.add('show');clearTimeout(showNotice.timer);showNotice.timer=setTimeout(()=>n.classList.remove('show'),1150)}
function updateBars(){$('#health-fill').style.width=Math.max(0,player.health)+'%';$('#shield-fill').style.width=Math.max(0,player.shield*2)+'%';$('#health-num').textContent=Math.ceil(player.health);$('#shield-num').textContent=Math.ceil(player.shield)}
const keys={};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code.startsWith('Digit'))setWeapon(+e.code.slice(5)-1);if(e.code==='KeyR')reload();if(e.code==='Space')jump()});window.addEventListener('keyup',e=>keys[e.code]=false);
let locked=false;renderer.domElement.addEventListener('click',()=>{if(playing&&!isTouch&&!locked)renderer.domElement.requestPointerLock?.();if(playing&&!isTouch&&locked)shoot()});document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===renderer.domElement);
document.addEventListener('mousemove',e=>{if(!playing)return;if(locked){player.yaw-=e.movementX*.0025;player.pitch=Math.max(-.55,Math.min(.5,player.pitch-e.movementY*.002))}});
window.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('mousedown',e=>{if(e.button===0&&playing&&!isTouch&&locked)shoot()});
function jump(){if(playing&&player.grounded){player.vy=7.8;player.grounded=false}}
function reload(){const w=weapons[selected];if(w.reloading||w.ammo===w.mag||w.reserve<=0)return;w.reloading=w.reload;showNotice('RELOADING');}
function finishReload(w){const n=Math.min(w.mag-w.ammo,w.reserve);w.ammo+=n;w.reserve-=n;w.reloading=0;$('#ammo').textContent=w.ammo;$('#reserve').textContent='/ '+w.reserve}
function damageBot(bot,amount){if(!bot.userData.alive)return;bot.userData.hp-=amount;const body=bot.children[0];body.material.emissive=new THREE.Color(0x992d34);body.material.emissiveIntensity=.9;setTimeout(()=>{if(body.material)body.material.emissiveIntensity=0},100);if(bot.userData.hp<=0){bot.userData.alive=false;bot.visible=false;kills++;$('#score').textContent=`${kills} / 8`;showNotice(kills===8?'ISLAND CHAMPION!':'RIVAL DOWN');if(kills===8)endGame(true)}}
function createBurst(pos,color=0x65edff,count=8){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.07+Math.random()*.06,5,4),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);effects.push({mesh:m,life:.35+Math.random()*.32,vel:new THREE.Vector3((Math.random()-.5)*5,Math.random()*5,(Math.random()-.5)*5)})}}
function fireRay(w){camera.getWorldDirection(tmpV);const origin=camera.position.clone();const direction=tmpV.clone();direction.x+=(Math.random()-.5)*w.spread;direction.y+=(Math.random()-.5)*w.spread;direction.z+=(Math.random()-.5)*w.spread;direction.normalize();raycaster.set(origin,direction);const targets=[];for(const b of bots)if(b.userData.alive)b.traverse(o=>{if(o.isMesh)targets.push(o)});const hits=raycaster.intersectObjects(targets,false);let end=origin.clone().addScaledVector(direction,70);if(hits.length){const hit=hits[0];end.copy(hit.point);const id=hit.object.userData.botId;const bot=bots[id];if(bot){damageBot(bot,w.damage);createBurst(hit.point,w.kind==='rocket'?0xffa45a:0x5ef3ff,5)}}
 const color=w.kind==='rocket'?0xffa14d:w.kind==='ak'?0xffd57a:w.kind==='dual'?0x9b80ff:0x62f5ff;const geo=new THREE.BufferGeometry().setFromPoints([origin.clone().addScaledVector(direction,.5),end]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.9}));scene.add(line);effects.push({mesh:line,life:.09,vel:new THREE.Vector3()});muzzle.color.setHex(color);muzzle.intensity=2.5;setTimeout(()=>muzzle.intensity=0,55);
}
function shoot(){if(!playing||ended)return;const w=weapons[selected],now=performance.now()/1000;if(now-lastShot<w.rate||w.reloading)return;if(w.ammo<=0){showNotice('TAP ↻ TO RELOAD');return}lastShot=now;w.ammo--;$('#ammo').textContent=w.ammo;if(w.kind==='rocket'){camera.getWorldDirection(tmpV);const p=new THREE.Mesh(new THREE.SphereGeometry(.21,8,6),new THREE.MeshBasicMaterial({color:0xff9a47}));p.position.copy(camera.position).addScaledVector(tmpV,1);scene.add(p);projectiles.push({mesh:p,vel:tmpV.clone().multiplyScalar(w.speed),life:2.4,rocket:true})}else fireRay(w)}
function botShoot(bot){const origin=bot.position.clone().add(new THREE.Vector3(0,1.5,0)),target=new THREE.Vector3(player.x,player.y-.25,player.z),dir=target.sub(origin).normalize();dir.x+=(Math.random()-.5)*.11;dir.y+=(Math.random()-.5)*.09;dir.z+=(Math.random()-.5)*.11;dir.normalize();const mesh=new THREE.Mesh(new THREE.SphereGeometry(.13,7,5),new THREE.MeshBasicMaterial({color:0xff6081,emissive:0x7d1436}));mesh.position.copy(origin);scene.add(mesh);enemyShots.push({mesh,vel:dir.multiplyScalar(18),life:3})}
function damagePlayer(amount){let left=amount;if(player.shield>0){const absorbed=Math.min(player.shield,left);player.shield-=absorbed;left-=absorbed}player.health=Math.max(0,player.health-left);damageFlash=.22;updateBars();if(player.health<=0)endGame(false)}
function movePlayer(dt){let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);forward+=stickY;side+=stickX;const len=Math.hypot(forward,side);if(len>1){forward/=len;side/=len}const sin=Math.sin(player.yaw),cos=Math.cos(player.yaw);let dx=side*cos+forward*sin,dz=side*sin-forward*cos;const nx=player.x+dx*player.speed*dt,nz=player.z+dz*player.speed*dt;
 function blocked(x,z){if(Math.abs(x)>39||Math.abs(z)>39)return true;for(const h of houseRects){const [hx,hz,hw,hd]=h;if(Math.abs(x-hx)<hw&&Math.abs(z-hz)<hd)return true}for(const [cx,cz,s] of crateRects)if(Math.abs(x-cx)<s&&Math.abs(z-cz)<s)return true;return false}
 if(!blocked(nx,player.z))player.x=nx;if(!blocked(player.x,nz))player.z=nz;player.vy-=19*dt;player.y+=player.vy*dt;if(player.y<1.7){player.y=1.7;player.vy=0;player.grounded=true}avatar.position.set(player.x,player.y-1.7,player.z);avatar.rotation.y=player.yaw;playerGun.rotation.y=0;
}
// Collider approximations for structures; doors/windows are visual only.
const houseRects=[[-16,-15,3.8,3.3],[17,-18,3.8,3.3],[-20,17,3.6,3.2],[20,18,3.8,3.3],[-34,-1,3,2.7],[34,2,3,2.7]],crateRects=[[-8,-20,1.25],[10,-10,1.25],[-24,7,1.25],[24,-8,1.25],[-12,23,1.25],[9,24,1.25],[31,12,1.25],[-31,-14,1.25]];

function updateBots(dt){for(const b of bots){const u=b.userData;if(!u.alive)continue;const dx=player.x-b.position.x,dz=player.z-b.position.z,dist=Math.hypot(dx,dz)||1;u.phase+=dt;u.fire-=dt;
 if(dist>8){const speed=2.2+(.2*Math.sin(u.phase));let nx=b.position.x+dx/dist*speed*dt,nz=b.position.z+dz/dist*speed*dt;if(Math.abs(nx)<39&&Math.abs(nz)<39){b.position.x=nx;b.position.z=nz}b.rotation.y=Math.atan2(dx,dz)}else{b.rotation.y=Math.atan2(dx,dz);b.position.x+=Math.sin(u.phase*1.6+iOffset(u.id))*.3*dt;b.position.z+=Math.cos(u.phase*1.4+iOffset(u.id))*.3*dt}
 b.position.y=Math.abs(Math.sin(u.phase*4))*.045;if(u.fire<=0&&dist<34){botShoot(b);u.fire=1.15+Math.random()*1.25}
 }}function iOffset(i){return i*7}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);let hitBot=null;for(const b of bots)if(b.userData.alive&&b.position.distanceTo(p.mesh.position)<1.1){hitBot=b;break}if(hitBot||p.life<=0||Math.abs(p.mesh.position.x)>44||Math.abs(p.mesh.position.z)>44){if(p.rocket){const pos=p.mesh.position.clone();createBurst(pos,0xff963f,22);for(const b of bots)if(b.userData.alive){const d=b.position.distanceTo(pos);if(d<7)damageBot(b,Math.max(20,95*(1-d/8)))}if(pos.distanceTo(new THREE.Vector3(player.x,0,player.z))<5&&hitBot)damagePlayer(5)}else if(hitBot)damageBot(hitBot,20);scene.remove(p.mesh);projectiles.splice(i,1)}}}
function updateShots(dt){for(let i=enemyShots.length-1;i>=0;i--){const s=enemyShots[i];s.life-=dt;s.mesh.position.addScaledVector(s.vel,dt);const dx=s.mesh.position.x-player.x,dz=s.mesh.position.z-player.z,dy=s.mesh.position.y-(player.y-.2);if(Math.hypot(dx,dz)<.72&&Math.abs(dy)<.9){damagePlayer(7);createBurst(s.mesh.position,0xff526f,4);s.life=-1}if(s.life<=0){scene.remove(s.mesh);enemyShots.splice(i,1)}}}
